import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

class AuthScreen extends StatefulWidget { const AuthScreen({super.key, this.startRegister = false}); final bool startRegister; @override State<AuthScreen> createState()=>_AuthScreenState(); }
class _AuthScreenState extends State<AuthScreen> {
 final _form=GlobalKey<FormState>(); final _name=TextEditingController(); final _email=TextEditingController(); final _password=TextEditingController(); final _phone=TextEditingController(); late bool _register=widget.startRegister; bool _busy=false;
