 Future<void> _submit() async { if(!_form.currentState!.validate())return;setState(()=>_busy=true);try{final auth=Supabase.instance.client.auth;if(_register){await auth.signUp(email:_email.text.trim(),password:_password.text, data:{'full_name':_name.text.trim(),'phone_number':_phone.text.trim()});}else{await auth.signInWithPassword(email:_email.text.trim(),password:_password.text);}if(mounted&&_register&&auth.currentSession==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Check your email to confirm your account, then sign in.')));setState(()=>_register=false);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>_busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Form(key:_form,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const CircleAvatar(radius:34,backgroundColor:Color(0xFF843A3A),child:Icon(Icons.school,color:Colors.white,size:36)),const SizedBox(height:12),const Text('Lenyora Primary School',textAlign:TextAlign.center,style:TextStyle(fontSize:21,fontWeight:FontWeight.bold,color:Color(0xFF843A3A))),Text(_register?'Parent Registration':'Parent Login',textAlign:TextAlign.center),const SizedBox(height:22),if(_register)...[TextFormField(controller:_name,decoration:const InputDecoration(labelText:'Full name',border:OutlineInputBorder()),validator:(v)=>v==null||v.trim().isEmpty?'Enter your full name':null),const SizedBox(height:12),TextFormField(controller:_phone,decoration:const InputDecoration(labelText:'Phone number',border:OutlineInputBorder()),validator:(v)=>v==null||v.trim().isEmpty?'Enter your phone number':null),const SizedBox(height:12)],TextFormField(controller:_email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email address',border:OutlineInputBorder()),validator:(v)=>v==null||!v.contains('@')?'Enter a valid email':null),const SizedBox(height:12),TextFormField(controller:_password,obscureText:true,decoration:const InputDecoration(labelText:'Password (at least 8 characters)',border:OutlineInputBorder()),validator:(v)=>v==null||v.length<8?'Use at least 8 characters':null),const SizedBox(height:18),FilledButton(onPressed:_busy?null:_submit,child:Text(_busy?'Please wait...':_register?'Create account':'Login')),TextButton(onPressed:()=>setState(()=>_register=!_register),child:Text(_register?'Already registered? Sign in':'New parent? Create an account')),TextButton(onPressed:()async{if(_email.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter your email address first.')));return;}try{await Supabase.instance.client.auth.resetPasswordForEmail(_email.text.trim());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Password reset email requested.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},child:const Text('Forgot password?'))]))))))));
